import {h,icon,button as btn} from './ui.mjs';
import {levels,lessons} from './course.mjs';
import {learningPath} from './learning-path.mjs';

export function renderLevelSelect(state,id='route-level'){
 return `<label class="route-level" for="${id}"><span>Уровень материала</span><select id="${id}" data-setting="level">${Object.entries(levels).map(([level,item])=>`<option value="${level}" ${state.settings.level===level?'selected':''}>${level} · ${h(item.name)}</option>`).join('')}</select></label>`;
}
function pathRow(l,index,state){
 const result=state.completed[l.id],mastered=(result?.best||0)>=80;
 return `<li><button class="path-row ${mastered?'mastered':result?'attempted':''}" data-action="route-lesson" data-id="${l.id}"><span class="path-number">${mastered?icon('check'):index+1}</span><span><b>${h(l.title)}</b><small>${h(l.subtitle||l.level)}</small></span><span class="path-score">${result?result.best+'%':icon('arrow')}</span></button></li>`;
}
export function renderLearningPath(c,modeControls=''){
 const s=c.state,path=learningPath(lessons,s),next=path.next,session=c.session,same=session&&session.lessonId===next?.id;
 return `<section class="learning-route panel" aria-label="Последовательный маршрут"><div class="route-heading"><div><span class="eyebrow">ТВОЙ ПОРЯДОК ЗАНЯТИЙ</span><h2>${path.completed?'Продолжай с нужного места.':'Начни с первого урока.'}</h2></div>${renderLevelSelect(s)}</div>${next?`<div class="route-next"><div><small>Урок ${path.position} из ${path.total}${s.completed[next.id]?' · закрепить ещё раз':''}</small><h3>${h(next.title)}</h3><p>${h(next.subtitle)} · ${next.items.length} заданий</p></div>${btn(`${same?'Продолжить урок':s.completed[next.id]?'Закрепить тему':'Начать урок'} ${icon('arrow')}`,same?'resume':'route-lesson','primary',`data-id="${next.id}"`)}</div>`:`<div class="route-next"><div><h3>Этот уровень закреплён.</h3><p>Выбери следующий уровень или повтори пройденное.</p></div><button class="btn secondary" data-page="progress">Мой прогресс</button></div>`}<p class="route-description">${h(levels[path.level].description)}. С нуля выбирай A1 и режим с вариантами. Уровень можно менять без потери результатов.</p>${modeControls?`<div class="route-mode"><span>Как отвечать</span>${modeControls}</div>`:''}<div class="route-counts"><span><b>${path.completed} / ${path.total}</b> пройдено</span><span><b>${path.mastered}</b> закреплено</span><button class="text-button" data-page="progress">Все результаты ${icon('arrow')}</button></div><div class="meter"><span style="width:${path.total?path.mastered/path.total*100:0}%"></span></div>${session&&!same?`<div class="saved-route"><span>Сохранённое занятие: <b>${h(session.title)}</b></span>${btn('Продолжить','resume','secondary')}</div>`:''}<div class="route-how"><span>${icon('book')} Прочитай правило и послушай пример</span><span>${icon('cards')} Выполни короткий урок</span><span>${icon('repeat')} Вернись к назначенным повторениям</span></div><p class="field-note">80% — тема закреплена, маршрут ведёт дальше. Урок с меньшим результатом можно улучшить. Любую тему можно открыть из списка.</p><details class="route-map"><summary>${icon('layers')} Все уроки уровня ${path.level} · ${path.total}</summary><ol class="path-list">${path.items.map((l,i)=>pathRow(l,i,s)).join('')}</ol></details></section>`;
}
export function renderCompletedProgress(state){
 return `<section class="completed-overview"><div class="section-title"><div><h2>Какие уроки пройдены</h2><p>Результат сохраняется после завершения урока.</p></div></div>${Object.keys(levels).map(level=>{const path=learningPath(lessons,state,level),done=path.items.filter(l=>state.completed[l.id]);return `<details class="completed-level panel"><summary><b>${level}</b><span>${path.completed} / ${path.total} пройдено · ${path.mastered} закреплено</span>${icon('chevron')}</summary>${done.length?`<ol class="path-list">${done.map(l=>pathRow(l,path.items.indexOf(l),state)).join('')}</ol>`:'<p class="field-note">Здесь пока нет завершённых уроков.</p>'}</details>`;}).join('')}</section>`;
}
